import type { Column, Typed } from '../Column'
import type { Record } from '../Record'
import type { TableName } from '../Table'

export type ReferenceColumnType<
    RefTable extends TableName = TableName,
    Type extends Record<RefTable> | Now.Internal.ExplicitKey | Now.Internal.TableBrand<RefTable> | string =
        | Record<RefTable>
        | Now.Internal.ExplicitKey
        | Now.Internal.TableBrand<RefTable>
        | string, // Allowing strings to be assigned is an escape hatch
    Default extends Type = Type,
> = Column<Type, Default> & {
    /** Reference a different table as string, escape with `` if definition not present locally (import from `@servicenow/sdk-core/global`) */
    referenceTable: RefTable
    /** Configure what happens to records that reference a record when that record is deleted. */
    cascadeRule?: 'none' | 'delete_no_workflow' | 'cascade' | 'delete' | 'restrict' | 'clear'
    /** Specifies the type of reference qualifier applied to the field */
    useReferenceQualifier?: 'simple' | 'dynamic' | 'advanced'
    /** Dynamic reference qualifier (use with useReferenceQualifier='dynamic'). Mutually exclusive with referenceQual. */
    dynamicRefQual?: Record<'sys_filter_option_dynamic'> | string
} & (
        | {
              /** Referenced table's form has an "edit" button in the related list for the current table */
              referenceFloats?: boolean
              /** Populate a new record from a reference field based on the field value */
              dynamicCreationScript?: string
              /** If a reference is not found for a reference field then it allows the creation of that target */
              dynamicCreation?: boolean
              /** Specifies a field on the referenced table to store in the database instead of sys_id.
               *  The field must be unique and required on the referenced table (e.g., 'email' for sys_user). */
              referenceKey?: string
              /** Filter reference based on a filter condition or referenced value */
              referenceQual?: string
              /** Creates a many-to-many relationship. The value is the relationship label displayed as a
               *  related list on the referenced table (e.g., 'Members'). Generates a sys_collection entry
               *  when the bootstrap XML is processed by the platform.
               *  Applicable only for ServiceNow scoped applications. For all other scoped applications,
               *  define many-to-many relationships using the sys_m2m table instead. */
              mtom?: string
              /** @deprecated Use referenceFloats instead */
              reference_floats?: never
              /** @deprecated Use dynamicCreationScript instead */
              dynamic_creation_script?: never
              /** @deprecated Use dynamicCreation instead */
              dyamic_creation?: never
              /** @deprecated Use referenceKey instead */
              reference_key?: never
              /** @deprecated Use referenceQual instead */
              reference_qual?: never
          }
        | {
              /** @deprecated Use referenceFloats instead */
              reference_floats?: boolean
              /** @deprecated Use dynamicCreationScript instead */
              dynamic_creation_script?: string
              /** @deprecated Use dynamicCreation instead */
              dyamic_creation?: boolean
              /** @deprecated Use referenceKey instead */
              reference_key?: string
              /** @deprecated Use referenceQual instead */
              reference_qual?: string
              referenceFloats?: never
              dynamicCreationScript?: never
              dynamicCreation?: never
              referenceKey?: never
              referenceQual?: never
          }
    )

/**
 * A Column for a reference type field.
 *
 * @see https://docs.servicenow.com/csh?topicname=table-api-now-ts.html&version=latest
 *
 * @group Table/Columns
 */
export function ReferenceColumn<
    const RefTable extends TableName,
    const Type extends
        | Record<RefTable>
        | Now.Internal.ExplicitKey<RefTable>
        | Now.Internal.TableBrand<RefTable>
        | string,
    const Default extends Type,
    const C extends ReferenceColumnType<RefTable, Type, Default>,
>(config: C & ReferenceColumnType<RefTable, Type, Default>) {
    return config as Typed<Type, C>
}
